let is_valid (c: Controller_itp.controller) goal =
  Session_itp.pn_proved c.Controller_itp.controller_session goal

let add_to_stat prover pr stat =
  (* add the result pr of the prover run of "prover" to the statistics table *)
  if Whyconf.Hprover.mem stat prover then
    add_to_prover_stat pr (Whyconf.Hprover.find stat prover)
  else
    Whyconf.Hprover.add stat prover
      Gnat_report.{ count = 1;
                    max_time = pr.Call_provers.pr_time;
                    max_steps = pr.Call_provers.pr_steps }

and proof_result_to_json prover r =
  let answer =
    Pp.sprintf "%a"
      Call_provers.print_prover_answer r.Call_provers.pr_answer in
  let steps =
    Gnat_config.back_convert_steps ~prover r.Call_provers.pr_steps in
  Json_base.Record [
    "time", Json_base.Float r.Call_provers.pr_time;
    "steps", Json_base.Int steps;
    "result", Json_base.String answer;
  ]

if Gnat_config.parallel > 1 then begin
  let provers =
    if warn then [Option.get (Gnat_config.prover_warn)] else Gnat_config.provers
  in
  let remaining = ref (List.length provers) in
  let callback pa pas =
    let prover =
      (Session_itp.get_proof_attempt_node s pa).Session_itp.prover.Whyconf.prover_name
    in
    if Gnat_config.logging then Logging.log g prover pas;
    if !remaining = 0 then ()
    else match pas with
      | Controller_itp.Done pr ->
        remaining := !remaining - 1;
        begin match pr.Call_provers.pr_answer with
        | Call_provers.Valid ->
          C.interrupt_proof_attempts_for_goal c g;
          remaining := 0;
          callback pa pas
        | _ ->
          if !remaining = 0 then callback pa pas else ()
        end
      | _ -> ()
  in
  List.iter (fun p -> schedule_goal_with_prover ~callback c g p) provers

(* This is to be executed when scheduling ends *)
let ending c () =
  Debug.Stats.record_timing "gnatwhy3.run_vcs"
    (fun () -> C.remove_all_valid_ce_attempt c.Controller_itp.controller_session);
  Debug.Stats.record_timing "gnatwhy3.save_session" (fun () -> C.save_session c);
  Gnat_checks.iter (report_messages c);
  let s = Buffer.contents escape_buffer in
  if s <> "" then
    Gnat_report.add_warning s;
  Gnat_report.print_messages ();
  (* Dump profiling data (when compiled with profiling enabled) to file whose
     name is based on the processed .mlw file; otherwise profile data from
     several compilation would be written to a single gmon.out file and
     overwrite each other. When compiled with profiling disabled it has no
     visible effect. Note: we set the filename just before the program exit
     to not interfere with profiling of provers.
   *)
  let basename =
    Filename.chop_extension
      (Filename.basename Gnat_config.filename) in
  Unix.putenv "GMON_OUT_PREFIX" (basename ^ "_gnatwhy3_gmon.out")

let get_msg (check, m) =
  Record (
    List.concat [
      [ "id", Int check.Gnat_expl.id ;
        "check_kind", String (Gnat_expl.check_kind_to_ada check.Gnat_expl.check_kind) ;
        "result", Bool m.result ;
        "check_tree", m.check_tree ;
        "extra_info", get_extra_info m.extra_info ;
        "unproved_status", get_unproved_status m.unproved_status
      ] ;
      get_stats (m.stats, m.stats_checker);
      ["cntexmps", List (get_cntexmp_models m.cntexmp_models)];
      get_manual_proof_info m.manual_proof
    ]
  )

(* In case several models are returned by Why3, we sort them by id. *)
let sort_messages (l : (Gnat_expl.check * msg) list) =
  List.sort (fun x y -> compare (fst x).Gnat_expl.id (fst y).Gnat_expl.id) l

let get_results () =
  let msg_set =
    Gnat_expl.HCheck.fold (fun k v acc -> (k,v) :: acc) msg_set []
  in
  "results", List (List.map get_msg (sort_messages msg_set))

let get_warnings () =
  match !warning_list with
  | [] -> []
  | l -> [("warnings", List (List.map (fun elem -> String elem) l))]

let get_timings () =
  let l = Hashtbl.fold (fun k v acc -> (k,v)::acc) (Debug.Stats.get_timings ()) [] in
  let get_name s = s in
  "timings", Record (List.map (fun (k,(v,_n)) -> get_name k, StandardFloat v) l)

let get_entity () =
  "entity", Int Gnat_config.entity

(* The main function, where we build the final Record to be printed using
Why3.Json_base.print_json function. *)
let print_messages () =
  print_json_single_line Format.std_formatter (
    Record (
      List.concat [
        [get_results (); get_timings (); get_entity ()];
        get_warnings ()
      ]
    )
  )

void CommandExecutor::printStatistics(std::ostream& out) const
{
  if (d_solver->getOptionInfo("stats").boolValue())
  {
    {
      const auto& stats = d_solver->getStatistics();
      auto it =
          stats.begin(d_solver->getOptionInfo("stats-internal").boolValue(),
                      d_solver->getOptionInfo("stats-all").boolValue());
      for (; it != stats.end(); ++it)
      {
        out << it->first << " = " << it->second << std::endl;
      }
    }
    {
      const auto& stats = d_solver->getTermManager().getStatistics();
      auto it =
          stats.begin(d_solver->getOptionInfo("stats-internal").boolValue(),
                      d_solver->getOptionInfo("stats-all").boolValue());
      for (; it != stats.end(); ++it)
      {
        out << it->first << " = " << it->second << std::endl;
      }
    }
  }
}

void CommandExecutor::printStatisticsSafe(int fd) const
{
  if (d_solver->getOptionInfo("stats").boolValue())
  {
    d_solver->getTermManager().printStatisticsSafe(fd);
    d_solver->printStatisticsSafe(fd);
  }
}

std::unique_ptr<std::ostream> openOStream(const std::string& filename)
{
  errno = 0;
  std::unique_ptr<std::ostream> res = std::make_unique<std::ofstream>(filename);
  if (!res || !*res)
  {
    std::stringstream ss;
    ss << "Cannot open file: `" << filename << "': " << cvc5_errno_failreason();
    throw OptionException(ss.str());
  }
  return res;

ManagedErr::ManagedErr() : ManagedStream(&std::cerr, "stderr") {}
bool ManagedErr::specialCases(const std::string& value)
{
  if (value == "stderr" || value == "--")
  {
    d_nonowned = &std::cerr;
    d_owned.reset();
    d_description = "stderr";
    return true;
  }
  else if (value == "stdout")
  {
    d_nonowned = &std::cout;
    d_owned.reset();
    d_description = "stdout";
    return true;
  }
  return false;
}
